style.css:
@-moz-document domain("roblox.com") {
body {
    background: url('https://i.pinimg.com/originals/7c/2a/90/7c2a9051c8a66e5b2863001300a878a4.gif') no-repeat center center fixed !important;
    background-size: cover !important;
    overflow-x: hidden !important;
  }

  /* Optional dark overlay */
  body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.4);
    z-index: 9999;
    pointer-events: none;
  }
}
